/* Harbourside Physiotherapy front desk.
   One accent (teal), one radius scale (8px panels, 6px controls, full pill for status chips),
   light and dark both follow the system setting. */

:root {
  color-scheme: light dark;

  --bg: #eef2f1;
  --surface: #fafcfb;
  --surface-sunk: #f2f5f4;
  --ink: #16201e;
  --ink-2: #44514e;
  --muted: #5b6865;
  --line: #d9e1df;
  --line-strong: #c2cdca;

  --accent: #0d6b66;
  --accent-ink: #f4fbfa;
  --accent-soft: #dcefec;

  --good: #276b33;
  --good-soft: #e3f1e4;
  --warn: #8a5a00;
  --warn-soft: #fbefd5;
  --crit: #a3271f;
  --crit-soft: #f8e2df;

  /* sequential teal, light to dark; text flips to light from step 4 */
  --heat-1: #e4f1ef;
  --heat-2: #c3e2dd;
  --heat-3: #92c9c1;
  --heat-4: #4fa198;
  --heat-5: #23807a;
  --heat-6: #105753;
  --heat-ink-dark: #16201e;
  --heat-ink-light: #f4fbfa;

  --shadow: 0 1px 2px rgb(22 50 46 / .06), 0 4px 16px rgb(22 50 46 / .05);
  --r-panel: 8px;
  --r-ctl: 6px;

  --font: "Avenir Next", "Segoe UI Variable Text", "Segoe UI", "Helvetica Neue", system-ui, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f1514;
    --surface: #161e1d;
    --surface-sunk: #1b2524;
    --ink: #e5ecea;
    --ink-2: #bcc8c5;
    --muted: #93a19e;
    --line: #273331;
    --line-strong: #34433f;

    --accent: #5cc0b5;
    --accent-ink: #0c1716;
    --accent-soft: #1d3633;

    --good: #7fcf8a;
    --good-soft: #1b3020;
    --warn: #e6b65c;
    --warn-soft: #362a12;
    --crit: #f08b80;
    --crit-soft: #3d1d1a;

    /* dark ramp is its own selection: dim to bright, text flips to dark from step 4 */
    --heat-1: #1b2a28;
    --heat-2: #1e403c;
    --heat-3: #225c56;
    --heat-4: #2f8a80;
    --heat-5: #55b0a5;
    --heat-6: #94d6cc;
    --heat-ink-dark: #0c1716;
    --heat-ink-light: #e5ecea;

    --shadow: 0 1px 2px rgb(0 0 0 / .3);
  }
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  min-height: 100dvh;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.45;
  font-variant-numeric: tabular-nums;
}

p, h1, h2, ol { margin: 0; }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.skip {
  position: absolute; left: 1rem; top: -3rem;
  background: var(--accent); color: var(--accent-ink);
  padding: .5rem .875rem; border-radius: var(--r-ctl); z-index: 10;
}
.skip:focus { top: .75rem; }

:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* ---------- top bar ---------- */
.topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  padding: .875rem clamp(1rem, 3vw, 2rem);
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: .75rem; }
.brand-mark {
  display: grid; place-items: center;
  width: 2.25rem; height: 2.25rem; border-radius: var(--r-ctl);
  background: var(--accent); color: var(--accent-ink);
  font-weight: 700; font-size: 1.05rem;
}
.brand-name { font-weight: 650; font-size: 1rem; letter-spacing: -.01em; }
.brand-sub, .today-sub { color: var(--muted); font-size: .8125rem; }
.today { text-align: right; }
.today-date { font-weight: 600; }

/* ---------- page ---------- */
.page {
  max-width: 1400px; margin: 0 auto;
  padding: clamp(1rem, 2.5vw, 1.75rem) clamp(1rem, 3vw, 2rem) 3rem;
  display: grid; gap: 1.25rem;
}

/* ---------- KPIs: plain figures, separated by rules, not cards ---------- */
.kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-panel);
  box-shadow: var(--shadow);
}
.kpi { padding: 1rem 1.25rem; }
.kpi + .kpi { border-left: 1px solid var(--line); }
.kpi-label { color: var(--ink-2); font-size: .8125rem; font-weight: 550; }
.kpi-value { font-size: 2rem; font-weight: 650; letter-spacing: -.02em; line-height: 1.15; margin-top: .25rem; }
.kpi-note { color: var(--muted); font-size: .8125rem; margin-top: .125rem; }

/* ---------- panels ---------- */
.layout {
  display: grid; gap: 1.25rem;
  grid-template-columns: minmax(0, 1.75fr) minmax(0, 1fr);
  grid-template-areas: "appts calls" "util util";
  align-items: start;
}
.panel-appts { grid-area: appts; }
.panel-calls { grid-area: calls; }
.panel-util  { grid-area: util; position: relative; }

.panel {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--r-panel); box-shadow: var(--shadow);
  min-width: 0;
}
.panel-head {
  display: flex; justify-content: space-between; align-items: flex-end; gap: 1rem; flex-wrap: wrap;
  padding: 1rem 1.25rem .875rem;
  border-bottom: 1px solid var(--line);
}
h1, h2 { font-size: 1.0625rem; font-weight: 650; letter-spacing: -.01em; }
.panel-sub { color: var(--muted); font-size: .8125rem; margin-top: .125rem; max-width: 65ch; }

/* ---------- filters ---------- */
.filters { display: flex; align-items: flex-end; gap: 1rem; flex-wrap: wrap; }
.field { display: grid; gap: .25rem; }
.field label { font-size: .75rem; font-weight: 600; color: var(--ink-2); }
.field-check { display: flex; align-items: center; gap: .5rem; padding-bottom: .4rem; }
.field-check label { font-size: .8125rem; font-weight: 500; color: var(--ink); cursor: pointer; }
.field-check input { width: 1rem; height: 1rem; accent-color: var(--accent); margin: 0; cursor: pointer; }
select {
  font: inherit; font-size: .875rem; color: var(--ink);
  background: var(--surface-sunk); border: 1px solid var(--line-strong); border-radius: var(--r-ctl);
  padding: .4rem 2rem .4rem .625rem; min-width: 11rem;
}

/* ---------- appointments table ---------- */
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; }
.appts th {
  text-align: left; font-size: .75rem; font-weight: 600; color: var(--muted);
  padding: .625rem 1.25rem .5rem; white-space: nowrap;
}
.appts td { padding: .625rem 1.25rem; border-top: 1px solid var(--line); vertical-align: top; }
.appts td.t { font-weight: 600; white-space: nowrap; width: 1%; }
.appts .t small { display: block; color: var(--muted); font-weight: 400; font-size: .75rem; }
.appts .who { font-weight: 550; }
.appts .who small, .appts .sess small { display: block; color: var(--muted); font-weight: 400; font-size: .8125rem; }
.appts tr.is-done td { color: var(--muted); }
.appts tr.is-done .who { font-weight: 450; }
.appts tr.is-now td { background: var(--accent-soft); }
.appts tr.is-now td:first-child { box-shadow: inset 3px 0 0 var(--accent); }

/* "now" marker row */
.now-row td {
  padding: 0 1.25rem; border-top: 0; height: 0;
}
.now-line {
  display: flex; align-items: center; gap: .5rem;
  color: var(--accent); font-size: .75rem; font-weight: 650;
  margin: -.5rem 0;
}
.now-line::after { content: ""; flex: 1; height: 2px; background: var(--accent); border-radius: 2px; }

/* status chips: text always present, colour reinforces it */
.chip {
  display: inline-flex; align-items: center; gap: .375rem; white-space: nowrap;
  font-size: .75rem; font-weight: 600; line-height: 1;
  padding: .3rem .55rem; border-radius: 999px; border: 1px solid transparent;
}
.chip::before { content: ""; width: .45rem; height: .45rem; border-radius: 999px; background: currentColor; }
.chip-booked  { color: var(--ink-2); border-color: var(--line-strong); }
.chip-booked::before { background: transparent; box-shadow: inset 0 0 0 1.5px currentColor; }
.chip-arrived { color: var(--good); background: var(--good-soft); }
.chip-insession { color: var(--accent-ink); background: var(--accent); }
