81	*, *::before, *::after { box-sizing: border-box; }
82	
83	html { -webkit-text-size-adjust: 100%; }
84	
85	body {
86	  margin: 0;
87	  min-height: 100dvh;
88	  background: var(--bg);
89	  color: var(--ink);
90	  font-family: var(--font);
91	  font-size: 15px;
92	  line-height: 1.45;
93	  font-variant-numeric: tabular-nums;
94	}
95	
96	p, h1, h2, ol { margin: 0; }
97	
98	.sr-only {
99	  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
100	  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
101	}
102	
103	.skip {
104	  position: absolute; left: 1rem; top: -3rem;
105	  background: var(--accent); color: var(--accent-ink);
106	  padding: .5rem .875rem; border-radius: var(--r-ctl); z-index: 10;
107	}
108	.skip:focus { top: .75rem; }
109	
110	:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
111	
112	/* ---------- top bar ---------- */
113	.topbar {
114	  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
115	  padding: .875rem clamp(1rem, 3vw, 2rem);
116	  background: var(--surface);
117	  border-bottom: 1px solid var(--line);
118	}
119	.brand { display: flex; align-items: center; gap: .75rem; }
120	.brand-mark {
121	  display: grid; place-items: center;
122	  width: 2.25rem; height: 2.25rem; border-radius: var(--r-ctl);
123	  background: var(--accent); color: var(--accent-ink);
124	  font-weight: 700; font-size: 1.05rem;
125	}
126	.brand-name { font-weight: 650; font-size: 1rem; letter-spacing: -.01em; }
127	.brand-sub, .today-sub { color: var(--muted); font-size: .8125rem; }
128	.today { text-align: right; }
129	.today-date { font-weight: 600; }
130	
131	/* ---------- page ---------- */
132	.page {
133	  max-width: 1400px; margin: 0 auto;
134	  padding: clamp(1rem, 2.5vw, 1.75rem) clamp(1rem, 3vw, 2rem) 3rem;
135	  display: grid; gap: 1.25rem;
136	}
137	
138	/* ---------- KPIs: plain figures, separated by rules, not cards ---------- */
139	.kpis {
140	  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
141	  background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-panel);
142	  box-shadow: var(--shadow);
143	}
144	.kpi { padding: 1rem 1.25rem; }
145	.kpi + .kpi { border-left: 1px solid var(--line); }
146	.kpi-label { color: var(--ink-2); font-size: .8125rem; font-weight: 550; }
147	.kpi-value { font-size: 2rem; font-weight: 650; letter-spacing: -.02em; line-height: 1.15; margin-top: .25rem; }
148	.kpi-note { color: var(--muted); font-size: .8125rem; margin-top: .125rem; }
149	
150	/* ---------- panels ---------- */
151	.layout {
152	  display: grid; gap: 1.25rem;
153	  grid-template-columns: minmax(0, 1.75fr) minmax(0, 1fr);
154	  grid-template-areas: "appts calls" "util util";
155	  align-items: start;
156	}
157	.panel-appts { grid-area: appts; }
158	.panel-calls { grid-area: calls; }
159	.panel-util  { grid-area: util; position: relative; }
160	
161	.panel {
162	  background: var(--surface); border: 1px solid var(--line);
163	  border-radius: var(--r-panel); box-shadow: var(--shadow);
164	  min-width: 0;
165	}
166	.panel-head {
167	  display: flex; justify-content: space-between; align-items: flex-end; gap: 1rem; flex-wrap: wrap;
168	  padding: 1rem 1.25rem .875rem;
169	  border-bottom: 1px solid var(--line);
170	}
171	h1, h2 { font-size: 1.0625rem; font-weight: 650; letter-spacing: -.01em; }
172	.panel-sub { color: var(--muted); font-size: .8125rem; margin-top: .125rem; max-width: 65ch; }
173	
174	/* ---------- filters ---------- */
175	.filters { display: flex; align-items: flex-end; gap: 1rem; flex-wrap: wrap; }
176	.field { display: grid; gap: .25rem; }
177	.field label { font-size: .75rem; font-weight: 600; color: var(--ink-2); }
178	.field-check { display: flex; align-items: center; gap: .5rem; padding-bottom: .4rem; }
179	.field-check label { font-size: .8125rem; font-weight: 500; color: var(--ink); cursor: pointer; }
180	.field-check input { width: 1rem; height: 1rem; accent-color: var(--accent); margin: 0; cursor: pointer; }
181	select {
182	  font: inherit; font-size: .875rem; color: var(--ink);
183	  background: var(--surface-sunk); border: 1px solid var(--line-strong); border-radius: var(--r-ctl);
184	  padding: .4rem 2rem .4rem .625rem; min-width: 11rem;
185	}
186	
187	/* ---------- appointments table ---------- */
188	.table-wrap { overflow-x: auto; }
189	table { width: 100%; border-collapse: collapse; }
190	.appts th {
191	  text-align: left; font-size: .75rem; font-weight: 600; color: var(--muted);
192	  padding: .625rem 1.25rem .5rem; white-space: nowrap;
193	}
194	.appts td { padding: .625rem 1.25rem; border-top: 1px solid var(--line); vertical-align: top; }
195	.appts td.t { font-weight: 600; white-space: nowrap; width: 1%; }
196	.appts .t small { display: block; color: var(--muted); font-weight: 400; font-size: .75rem; }
197	.appts .who { font-weight: 550; }
198	.appts .who small, .appts .sess small { display: block; color: var(--muted); font-weight: 400; font-size: .8125rem; }
199	.appts td.nw { white-space: nowrap; }
200	.appts .who small.m-only { display: none; }
201	.appts tr.is-done td { color: var(--muted); }
202	.appts tr.is-done .who { font-weight: 450; }
203	.appts tr.is-now td { background: var(--accent-soft); }
204	.appts tr.is-now td:first-child { box-shadow: inset 3px 0 0 var(--accent); }
205	
206	/* "now" marker row */
207	.now-row td {
208	  padding: 0 1.25rem; border-top: 0; height: 0;
209	}
210	.now-line {
211	  display: flex; align-items: center; gap: .5rem;
212	  color: var(--accent); font-size: .75rem; font-weight: 650;
213	  margin: -.5rem 0;
214	}
215	.now-line::after { content: ""; flex: 1; height: 2px; background: var(--accent); border-radius: 2px; }
216	
217	/* status chips: text always present, colour reinforces it */
218	.chip {
219	  display: inline-flex; align-items: center; gap: .375rem; white-space: nowrap;
220	  font-size: .75rem; font-weight: 600; line-height: 1;
221	  padding: .3rem .55rem; border-radius: 999px; border: 1px solid transparent;
222	}
223	.chip::before { content: ""; width: .45rem; height: .45rem; border-radius: 999px; background: currentColor; }
224	.chip-booked  { color: var(--ink-2); border-color: var(--line-strong); }
225	.chip-booked::before { background: transparent; box-shadow: inset 0 0 0 1.5px currentColor; }
226	.chip-arrived { color: var(--good); background: var(--good-soft); }
227	.chip-insession { color: var(--accent-ink); background: var(--accent); }
228	.chip-done    { color: var(--muted); background: var(--surface-sunk); }
229	.chip-done::before { border-radius: 1px; width: .5rem; height: .25rem; background: transparent;
230	  border-left: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor; transform: rotate(-45deg) translateY(-1px); }
231	.chip-late    { color: var(--warn); background: var(--warn-soft); }
232	.chip-noshow  { color: var(--crit); background: var(--crit-soft); }
233	.chip-noshow::before { border-radius: 1px; }
234	
235	.empty { padding: 2rem 1.25rem; color: var(--muted); font-size: .875rem; text-align: center; }
236	.empty-title { color: var(--ink); font-weight: 600; margin-bottom: .25rem; }
237	
238	/* ---------- follow-up calls ---------- */
239	.calls { list-style: none; padding: .25rem 0; }
240	.call {
241	  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: .25rem 1rem;
242	  padding: .875rem 1.25rem;
243	}
244	.call + .call { border-top: 1px solid var(--line); }
245	.call-name { font-weight: 600; }
246	.call-reason { color: var(--ink-2); font-size: .875rem; grid-column: 1 / -1; }
247	.call-meta {
248	  grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: .25rem 1rem;
249	  font-size: .8125rem; color: var(--muted);
250	}
251	.call-meta a { color: var(--ink-2); text-underline-offset: 2px; }
252	.due { font-size: .75rem; font-weight: 650; white-space: nowrap; align-self: start; padding-top: .15rem; }
253	.due-over { color: var(--crit); }
254	.due-today { color: var(--warn); }
255	.due-later { color: var(--muted); }
256	.call-actions { grid-column: 1 / -1; margin-top: .5rem; }
257	
258	.btn {
259	  font: inherit; font-size: .8125rem; font-weight: 600; cursor: pointer;
260	  padding: .45rem .8rem; border-radius: var(--r-ctl);
261	  border: 1px solid var(--accent); background: var(--accent); color: var(--accent-ink);
262	  transition: background-color .15s ease, transform .1s ease;
263	}
264	.btn:hover { background: color-mix(in oklab, var(--accent) 86%, var(--ink)); }
265	.btn:active { transform: translateY(1px); }
266	.btn-outline { background: transparent; color: var(--accent); border-color: var(--line-strong); }
267	.btn-outline:hover { background: var(--accent-soft); border-color: var(--accent); }
268	.btn-quiet { background: transparent; color: var(--accent); border-color: transparent; padding: .25rem .4rem; }
269	.btn-quiet:hover { background: var(--accent-soft); }
270	
271	.called { border-top: 1px solid var(--line); }
272	.called summary {
273	  cursor: pointer; padding: .75rem 1.25rem; font-size: .8125rem; font-weight: 600; color: var(--ink-2);
274	}
275	.called-list { list-style: none; padding: 0 1.25rem .75rem; display: grid; gap: .375rem; }
276	.called-list li {
277	  display: flex; justify-content: space-between; align-items: center; gap: .5rem;
278	  font-size: .8125rem; color: var(--muted);
279	}
280	
281	/* ---------- utilisation heatmap ---------- */
282	.legend { display: flex; align-items: center; gap: .5rem; font-size: .75rem; color: var(--muted); }
283	.legend-steps { display: inline-flex; gap: 2px; }
284	.legend-steps span { width: 1.25rem; height: .75rem; border-radius: 2px; }
285	
286	.heat { border-collapse: separate; border-spacing: 2px; padding: .75rem 1rem 1rem; min-width: 640px; table-layout: fixed; }
287	.heat col.c-room { width: 11rem; }
288	.heat col.c-week { width: 5.5rem; }
289	.heat th { font-size: .75rem; font-weight: 600; color: var(--muted); padding: .25rem .5rem; text-align: center; }
290	.heat th[scope="row"] { text-align: left; color: var(--ink); font-size: .875rem; white-space: nowrap; padding-right: 1rem; }
291	.heat th[scope="row"] small { display: block; color: var(--muted); font-weight: 400; font-size: .75rem; }
292	.heat thead th.is-today { color: var(--accent); }
293	.heat td {
294	  text-align: center; font-size: .8125rem; font-weight: 600;
295	  height: 3rem; border-radius: 4px; padding: 0 .25rem;
296	}
297	.heat td.cell { cursor: default; }
298	.heat td.cell:hover, .heat td.cell:focus-visible { box-shadow: inset 0 0 0 2px var(--ink); outline: none; }
299	.heat td.is-forecast { background-image: repeating-linear-gradient(135deg, transparent 0 6px, rgb(127 127 127 / .14) 6px 8px); }
300	.heat td.closed { color: var(--muted); font-weight: 400; background: var(--surface-sunk); }
301	.heat td.avg { font-size: .9375rem; font-weight: 650; color: var(--ink); background: transparent; }
302	.heat th.avg-h { color: var(--ink-2); }
303	
304	.h1 { background-color: var(--heat-1); color: var(--heat-ink-dark); }
305	.h2 { background-color: var(--heat-2); color: var(--heat-ink-dark); }
306	.h3 { background-color: var(--heat-3); color: var(--heat-ink-dark); }
307	.h4 { background-color: var(--heat-4); color: var(--heat-ink-light); }
308	.h5 { background-color: var(--heat-5); color: var(--heat-ink-light); }
309	.h6 { background-color: var(--heat-6); color: var(--heat-ink-light); }
310	@media (prefers-color-scheme: dark) {
311	  .h1, .h2, .h3 { color: var(--heat-ink-light); }
312	  .h4, .h5, .h6 { color: var(--heat-ink-dark); }
313	}
314	
315	.tooltip {
316	  position: absolute; pointer-events: none; z-index: 5;
317	  background: var(--ink); color: var(--surface);
318	  font-size: .8125rem; line-height: 1.35; padding: .5rem .65rem; border-radius: var(--r-ctl);
319	  box-shadow: var(--shadow); max-width: 16rem;
320	  transform: translate(-50%, calc(-100% - 8px));
321	}
322	.tooltip strong { display: block; font-weight: 650; }
323	
324	/* ---------- motion: row entry only, removed under reduced motion ---------- */
325	@media (prefers-reduced-motion: no-preference) {
326	  .call.leaving { opacity: 0; transform: translateX(8px); transition: opacity .2s ease, transform .2s ease; }
327	}
328	@media (prefers-reduced-motion: reduce) {
329	  *, *::before, *::after { transition: none !important; animation: none !important; }
330	}
331	
332	/* ---------- responsive ---------- */
333	@media (max-width: 1080px) {
334	  .layout { grid-template-columns: minmax(0, 1fr); grid-template-areas: "appts" "calls" "util"; }
335	}
336	@media (max-width: 760px) {
337	  .kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
338	  .kpi:nth-child(3) { border-left: 0; }
339	  .kpi:nth-child(n+3) { border-top: 1px solid var(--line); }
340	  .topbar { flex-direction: column; align-items: flex-start; }
341	  .today { text-align: left; }
342	  .appts th:nth-child(3), .appts td:nth-child(3),
343	  .appts th:nth-child(4), .appts td:nth-child(4),
344	  .appts th:nth-child(5), .appts td:nth-child(5) { display: none; }
345	  .appts .who small.m-only { display: block; }
346	  .heat col.c-room { width: 7.5rem; }
347	  .heat { min-width: 560px; }
348	  .appts th, .appts td { padding-left: .875rem; padding-right: .875rem; }
349	  .kpi-value { font-size: 1.625rem; }
350	}
