99	    var rows = APPOINTMENTS.filter(function (a) {
100	      if (who !== "all" && a.physio !== who) return false;
101	      if (hideFinished.checked && FINISHED[a.status]) return false;
102	      return true;
103	    });
104	
105	    var now = toMin(NOW);
106	    var html = "";
107	    var nowPlaced = false;
108	
