117	      html +=
118	        '<tr class="' + cls + '">' +
119	          '<td class="t">' + a.time + "<small>to " + endTime(a.time, a.mins) + "</small></td>" +
120	          '<td class="who">' + esc(a.patient) + "<small>" + esc(a.note) + '</small><small class="m-only">' + esc(a.physio) + ", " + esc(a.room) + "</small></td>" +
121	          '<td class="sess">' + esc(a.session) + "<small>" + a.mins + " min</small></td>" +
122	          '<td class="nw">' + esc(a.physio) + "</td>" +
123	          '<td class="nw">' + esc(a.room) + "</td>" +
124	          '<td><span class="chip ' + st.cls + '">' + st.label + "</span></td>" +
125	        "</tr>";
126	    });
