128	    $("appts-body").innerHTML = html;
129	    $("appts-empty").hidden = rows.length > 0;
130	
131	    var left = rows.filter(function (a) { return !FINISHED[a.status]; }).length;
132	    $("appts-count").textContent = rows.length === 0
