137	  physioSelect.addEventListener("change", renderAppointments);
138	  hideFinished.addEventListener("change", renderAppointments);
139	
140	  /* ---------------- utilisation heatmap ---------------- */
141	
142	  // thresholds for the six sequential steps
143	  var STEPS = [
144	    { max: 40,  cls: "h1", label: "under 40%" },
145	    { max: 55,  cls: "h2", label: "40 to 54%" },
146	    { max: 70,  cls: "h3", label: "55 to 69%" },
147	    { max: 80,  cls: "h4", label: "70 to 79%" },
148	    { max: 90,  cls: "h5", label: "80 to 89%" },
149	    { max: 101, cls: "h6", label: "90% or more" }
150	  ];
151	  function step(p) { for (var i = 0; i < STEPS.length; i++) if (p < STEPS[i].max) return STEPS[i]; return STEPS[STEPS.length - 1]; }
152	
153	  $("legend-steps").innerHTML = STEPS.map(function (s) {
154	    return '<span class="' + s.cls + '" title="' + s.label + '"></span>';
155	  }).join("");
