159	  }).join("") + '<th scope="col" class="avg-h">Week</th></tr>';
160	  $("heat-head").innerHTML = head;
161	  var cols = '<col class="c-room">' + DAYS.map(function () { return "<col>"; }).join("") + '<col class="c-week">';
162	  $("heat").insertAdjacentHTML("afterbegin", "<colgroup>" + cols + "</colgroup>");
163	
164	  var totalBooked = 0, totalSlots = 0;
165	  var bodyHtml = ROOMS.map(function (r) {
166	    var rb = 0, rs = 0;
167	    var cells = r.booked.map(function (b, i) {
168	      var d = DAYS[i];
169	      if (b === null) return '<td class="closed">Closed</td>';
170	      rb += b; rs += d.slots;
171	      var p = pct(b, d.slots);
172	      var s = step(p);
173	      var tip = r.name + ", " + d.label + "|" + b + " of " + d.slots + " slots booked (" + p + "%)" + (d.forecast ? ", bookings so far" : "");
174	      return '<td class="cell ' + s.cls + (d.forecast ? " is-forecast" : "") + '" tabindex="0" data-tip="' + esc(tip) +
175	             '" aria-label="' + esc(tip.replace("|", ": ")) + '">' + p + "%</td>";
176	    }).join("");
177	    totalBooked += rb; totalSlots += rs;
178	    return '<tr><th scope="row">' + esc(r.name) + "<small>" + esc(r.use) + "</small></th>" + cells +
179	           '<td class="avg">' + pct(rb, rs) + "%</td></tr>";
180	  }).join("");
181	
182	  // clinic-wide row
183	  var dayTotals = DAYS.map(function (d, i) {
184	    var b = 0, s = 0;
185	    ROOMS.forEach(function (r) { if (r.booked[i] !== null) { b += r.booked[i]; s += d.slots; } });
186	    return pct(b, s);
187	  });
188	  bodyHtml += '<tr><th scope="row">All rooms<small>Clinic total</small></th>' +
189	    dayTotals.map(function (p) { return '<td class="avg">' + p + "%</td>"; }).join("") +
190	    '<td class="avg">' + pct(totalBooked, totalSlots) + "%</td></tr>";
191	  $("heat-body").innerHTML = bodyHtml;
192	
193	  var tooltip = $("tooltip");
194	  var panel = tooltip.parentElement;
195	  function showTip(cell) {
196	    var parts = cell.getAttribute("data-tip").split("|");
197	    tooltip.innerHTML = "<strong>" + esc(parts[0]) + "</strong>" + esc(parts[1]);
198	    var pr = panel.getBoundingClientRect(), cr = cell.getBoundingClientRect();
199	    tooltip.style.left = (cr.left - pr.left + cr.width / 2) + "px";
200	    tooltip.style.top = (cr.top - pr.top) + "px";
201	    tooltip.hidden = false;
202	  }
203	  function hideTip() { tooltip.hidden = true; }
204	  var heat = $("heat");
205	  heat.addEventListener("mouseover", function (e) { var c = e.target.closest("td.cell"); if (c) showTip(c); });
206	  heat.addEventListener("mouseleave", hideTip);
207	  heat.addEventListener("focusin", function (e) { var c = e.target.closest("td.cell"); if (c) showTip(c); });
208	  heat.addEventListener("focusout", hideTip);
209	
210	  /* ---------------- follow-up calls ---------------- */
211	
212	  var called = [];
213	
214	  function dueLabel(due) {
215	    var d = daysBetween(TODAY, due);
216	    if (d < 0) return { text: "Overdue " + -d + (d === -1 ? " day" : " days"), cls: "due-over", rank: 0 };
217	    if (d === 0) return { text: "Due today", cls: "due-today", rank: 1 };
218	    if (d === 1) return { text: "Due tomorrow", cls: "due-later", rank: 2 };
219	    return { text: "Due in " + d + " days", cls: "due-later", rank: 2 };
220	  }
221	
222	  function renderCalls() {
223	    var open = FOLLOW_UPS.filter(function (f) { return called.indexOf(f.id) === -1; })
224	      .sort(function (a, b) { return Date.parse(a.due) - Date.parse(b.due); });
225	
226	    $("calls-list").innerHTML = open.map(function (f) {
227	      var due = dueLabel(f.due);
228	      return '<li class="call" data-id="' + f.id + '">' +
229	          '<p class="call-name">' + esc(f.name) + "</p>" +
230	          '<p class="due ' + due.cls + '">' + due.text + "</p>" +
231	          '<p class="call-reason">' + esc(f.reason) + "</p>" +
232	          '<p class="call-meta"><a href="tel:' + f.phone.replace(/\s/g, "") + '">' + esc(f.phone) + "</a>" +
233	            "<span>Last seen " + esc(f.last) + "</span><span>" + esc(f.physio) + "</span></p>" +
234	          '<div class="call-actions"><button type="button" class="btn btn-outline" data-act="called">Mark as called</button></div>' +
235	        "</li>";
236	    }).join("");
237	
238	    $("calls-empty").hidden = open.length > 0;
239	
240	    var urgent = open.filter(function (f) { return dueLabel(f.due).rank <= 1; }).length;
241	    var over = open.filter(function (f) { return dueLabel(f.due).rank === 0; }).length;
242	    $("calls-count").textContent = open.length === 0
243	      ? "Nothing waiting"
244	      : open.length + " waiting, " + over + " overdue";
245	
246	    $("kpi-calls").textContent = urgent;
247	    $("kpi-calls-note").textContent = over > 0 ? over + " overdue, oldest first in the list" : "None overdue";
248	
249	    var done = FOLLOW_UPS.filter(function (f) { return called.indexOf(f.id) !== -1; });
250	    $("called-wrap").hidden = done.length === 0;
251	    $("called-summary").textContent = "Called today (" + done.length + ")";
252	    $("called-list").innerHTML = done.map(function (f) {
253	      return '<li><span>' + esc(f.name) + '</span><button type="button" class="btn btn-quiet" data-act="undo" data-id="' +
254	             f.id + '">Undo</button></li>';
255	    }).join("");
256	  }
257	
258	  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
259	
260	  $("calls-list").addEventListener("click", function (e) {
261	    var btn = e.target.closest('button[data-act="called"]');
262	    if (!btn) return;
263	    var li = btn.closest(".call");
264	    var id = li.getAttribute("data-id");
265	    var commit = function () { called.push(id); renderCalls(); };
266	    if (reduceMotion.matches) { commit(); return; }
267	    li.classList.add("leaving");
268	    setTimeout(commit, 200);
269	  });
270	
271	  $("called-list").addEventListener("click", function (e) {
272	    var btn = e.target.closest('button[data-act="undo"]');
273	    if (!btn) return;
274	    var id = btn.getAttribute("data-id");
275	    called = called.filter(function (c) { return c !== id; });
276	    renderCalls();
277	  });
278	
279	  /* ---------------- KPIs ---------------- */
280	
281	  function renderKpis() {
282	    var total = APPOINTMENTS.length;
283	    var finished = APPOINTMENTS.filter(function (a) { return a.status === "done"; }).length;
284	    var noshow = APPOINTMENTS.filter(function (a) { return a.status === "noshow"; }).length;
285	    $("kpi-appts").textContent = total;
286	    $("kpi-appts-note").textContent = finished + " completed, " + noshow + " no-show";
287	
288	    var now = toMin(NOW);
289	    var upcoming = APPOINTMENTS.filter(function (a) { return a.status === "booked" || a.status === "late"; });
290	    $("kpi-remaining").textContent = upcoming.length;
291	    var next = upcoming.filter(function (a) { return toMin(a.time) >= now; })[0];
292	    $("kpi-next").textContent = next ? "Next: " + next.patient + " at " + next.time : "No more arrivals today";
293	
294	    $("kpi-util").textContent = pct(totalBooked, totalSlots) + "%";
295	    var lowest = ROOMS.map(function (r) {
296	      var b = 0, s = 0;
297	      r.booked.forEach(function (v, i) { if (v !== null) { b += v; s += DAYS[i].slots; } });
298	      return { name: r.name, p: pct(b, s) };
299	    }).sort(function (a, b) { return a.p - b.p; })[0];
300	    $("kpi-util-note").textContent = "Most free capacity: " + lowest.name + " (" + lowest.p + "%)";
301	  }
302	
303	  renderAppointments();
304	  renderCalls();
305	  renderKpis();
306	})();
