1	/* Harbourside Physiotherapy front desk.
2	   One accent (teal), one radius scale (8px panels, 6px controls, full pill for status chips),
3	   light and dark both follow the system setting. */
4	
5	:root {
6	  color-scheme: light dark;
7	
8	  --bg: #eef2f1;
9	  --surface: #fafcfb;
10	  --surface-sunk: #f2f5f4;
11	  --ink: #16201e;
12	  --ink-2: #44514e;
13	  --muted: #5b6865;
14	  --line: #d9e1df;
15	  --line-strong: #c2cdca;
16	
17	  --accent: #0d6b66;
18	  --accent-ink: #f4fbfa;
19	  --accent-soft: #dcefec;
20	
21	  --good: #276b33;
22	  --good-soft: #e3f1e4;
23	  --warn: #8a5a00;
24	  --warn-soft: #fbefd5;
25	  --crit: #a3271f;
26	  --crit-soft: #f8e2df;
27	
28	  /* sequential teal, light to dark; text flips to light from step 4 */
29	  --heat-1: #e4f1ef;
30	  --heat-2: #c3e2dd;
31	  --heat-3: #92c9c1;
32	  --heat-4: #26766e;
33	  --heat-5: #185f59;
34	  --heat-6: #0e4642;
35	  --heat-ink-dark: #16201e;
36	  --heat-ink-light: #f4fbfa;
37	
38	  --shadow: 0 1px 2px rgb(22 50 46 / .06), 0 4px 16px rgb(22 50 46 / .05);
39	  --r-panel: 8px;
40	  --r-ctl: 6px;
41	
42	  --font: "Avenir Next", "Segoe UI Variable Text", "Segoe UI", "Helvetica Neue", system-ui, sans-serif;
43	}
44	
45	@media (prefers-color-scheme: dark) {
46	  :root {
47	    --bg: #0f1514;
48	    --surface: #161e1d;
49	    --surface-sunk: #1b2524;
50	    --ink: #e5ecea;
51	    --ink-2: #bcc8c5;
52	    --muted: #93a19e;
53	    --line: #273331;
54	    --line-strong: #34433f;
55	
56	    --accent: #5cc0b5;
57	    --accent-ink: #0c1716;
58	    --accent-soft: #1d3633;
59	
60	    --good: #7fcf8a;
61	    --good-soft: #1b3020;
62	    --warn: #e6b65c;
63	    --warn-soft: #362a12;
64	    --crit: #f08b80;
65	    --crit-soft: #3d1d1a;
66	
67	    /* dark ramp is its own selection: dim to bright, text flips to dark from step 4 */
68	    --heat-1: #1b2a28;
69	    --heat-2: #1e403c;
70	    --heat-3: #225c56;
71	    --heat-4: #409d92;
72	    --heat-5: #6cc0b5;
73	    --heat-6: #a5ded5;
74	    --heat-ink-dark: #0c1716;
75	    --heat-ink-light: #e5ecea;
76	
77	    --shadow: 0 1px 2px rgb(0 0 0 / .3);
78	  }
79	}
80	
81	*, *::before, *::after { box-sizing: border-box; }
82	
83	html { -webkit-text-size-adjust: 100%; }
84	
85	body {
86	  margin: 0;
87	  min-height: 100dvh;
88	  background: var(--bg);
89	  color: var(--ink);
90	  font-family: var(--font);
91	  font-size: 16px;
92	  line-height: 1.45;
93	  font-variant-numeric: tabular-nums;
94	}
95	
96	p, h1, h2, ol { margin: 0; }
97	
98	.sr-only {
99	  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
100	  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
101	}
102	
103	.skip {
104	  position: absolute; left: 1rem; top: -3rem;
105	  background: var(--accent); color: var(--accent-ink);
106	  padding: .5rem .875rem; border-radius: var(--r-ctl); z-index: 10;
107	}
108	.skip:focus { top: .75rem; }
109	
110	:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
111	
112	/* ---------- top bar ---------- */
113	.topbar {
114	  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
115	  padding: .875rem clamp(1rem, 3vw, 2rem);
116	  background: var(--surface);
117	  border-bottom: 1px solid var(--line);
118	}
119	.brand { display: flex; align-items: center; gap: .75rem; }
120	.brand-mark {
121	  display: grid; place-items: center;
122	  width: 2.25rem; height: 2.25rem; border-radius: var(--r-ctl);
123	  background: var(--accent); color: var(--accent-ink);
124	  font-weight: 700; font-size: 1.125rem;
125	}
126	.brand-name { font-weight: 650; font-size: 1.125rem; letter-spacing: -.01em; }
127	.brand-sub, .today-sub { color: var(--muted); font-size: .875rem; }
128	.today { text-align: right; }
129	.today-date { font-weight: 600; }
130	
131	/* ---------- page ---------- */
132	.page {
133	  max-width: 1400px; margin: 0 auto;
134	  padding: clamp(1rem, 2.5vw, 1.75rem) clamp(1rem, 3vw, 2rem) 3rem;
135	  display: grid; gap: 1.25rem;
136	}
137	
138	/* ---------- KPIs: plain figures, separated by rules, not cards ---------- */
139	.kpis {
140	  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
141	  background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-panel);
142	  box-shadow: var(--shadow);
143	}
144	.kpi { padding: 1rem 1.25rem; }
145	.kpi + .kpi { border-left: 1px solid var(--line); }
146	.kpi-label { color: var(--ink-2); font-size: .875rem; font-weight: 550; }
147	.kpi-value { font-size: 2rem; font-weight: 650; letter-spacing: -.02em; line-height: 1.15; margin-top: .25rem; }
148	.kpi-note { color: var(--muted); font-size: .875rem; margin-top: .125rem; }
149	
150	/* ---------- panels ---------- */
151	.layout {
152	  display: grid; gap: 1.25rem;
153	  grid-template-columns: minmax(0, 1.75fr) minmax(0, 1fr);
154	  grid-template-areas: "appts calls" "util util";
155	  align-items: start;
156	}
157	.panel-appts { grid-area: appts; }
158	.panel-calls { grid-area: calls; }
159	.panel-util  { grid-area: util; position: relative; }
160	
